reproduction.framing_gd:
extends SceneTree
## Headless full-bout framing witness. Each box conservatively contains the
## skinned mesh: every positive-weight vertex lies in its influences' convex hull.
var room: Node
var camera: Camera3D
var envelopes: Array = []
var args: Dictionary = {}

func _initialize() -> void:
	for arg in OS.get_cmdline_user_args():
		var bits: PackedStringArray = arg.split("=", true, 1)
		if bits.size() == 2:
			args[bits[0]] = bits[1]
	call_deferred("run")

func collect(node: Node, player: RefCounted, bins: Array) -> void:
	if node is MeshInstance3D and node.mesh != null and node.is_visible_in_tree():
		var mesh: Mesh = node.mesh
		var skin: Skin = node.skin
		if skin == null:
			skin = player.skeleton().create_skin_from_rest_transforms()
		for surface in mesh.get_surface_count():
			var arrays: Array = mesh.surface_get_arrays(surface)
			var vertices: PackedVector3Array = arrays[Mesh.ARRAY_VERTEX]
			var bones: PackedInt32Array = arrays[Mesh.ARRAY_BONES]
			var weights: PackedFloat32Array = arrays[Mesh.ARRAY_WEIGHTS]
			if bones.is_empty():
				continue
			var stride: int = bones.size() / vertices.size()
			var bounds: Dictionary = {}
			for v in vertices.size():
				for w in stride:
					var at: int = v * stride + w
					if weights[at] <= 0.0:
						continue
					var bind: int = bones[at]
					var point: Vector3 = skin.get_bind_pose(bind) * vertices[v]
					bounds[bind] = (bounds[bind] as AABB).expand(point) if bounds.has(bind) else AABB(point, Vector3.ZERO)
			for bind in bounds:
				var bone: int = skin.get_bind_bone(bind)
				if not skin.get_bind_name(bind).is_empty():
					bone = player.skeleton().find_bone(skin.get_bind_name(bind))
				assert(bone >= 0)
				bins.append({"bone": bone, "box": bounds[bind]})
	for child in node.get_children():
		collect(child, player, bins)

func screen_box(player: RefCounted, bins: Array) -> Dictionary:
	var lo := Vector2(INF, INF)
	var hi := Vector2(-INF, -INF)
	var front: bool = true
	for bin in bins:
		var transform: Transform3D = player.skeleton_world() * player._pose_global(int(bin.bone))
		for corner in 8:
			var point: Vector3 = transform * (bin.box as AABB).get_endpoint(corner)
			front = front and not camera.is_position_behind(point)
			var pixel: Vector2 = camera.unproject_position(point)
			lo = lo.min(pixel)
			hi = hi.max(pixel)
	var size: Vector2 = camera.get_viewport().get_visible_rect().size
	return {"min": [lo.x, lo.y], "max": [hi.x, hi.y], "inside": front and lo.x >= 0.0 and lo.y >= 0.0 and hi.x <= size.x and hi.y <= size.y}

func run() -> void:
	room = load("res://scenes/FightWorldLive.tscn").instantiate()
	if args.has("room_script"):
		room.set_script(load(str(args.room_script)))
	assert(room.configure({"seed": 92012, "discipline": "mma", "strikes_play_whole": true,
		"reactions_play_whole": true, "contact_stop": true, "readable_onset": true,
		"human_speed_tempo": true, "walkout": false, "hit_cam": false,
		"camera_keep_pair": str(args.get("fit", "false")) == "true", "camera_shot": "establishing",
		"camera_follow": str(args.get("camera", "live")) != "pass1"}))
	root.add_child(room)
	assert(room.setup())
	room.set_process(false)
	camera = room._find_camera(room)
	if str(args.get("camera", "live")) == "pass1":
		camera.position = Vector3(3.4, 5.0, 6.0)
		camera.transform = Transform3D(Basis.looking_at(Vector3(0.0, 2.1, 0.0) - camera.position, Vector3.UP), camera.position)
		camera.fov = 48.0
	for pair in [[room._node_a, room._player_a], [room._node_b, room._player_b]]:
		var bins: Array = []
		collect(pair[0], pair[1], bins)
		assert(not bins.is_empty(), "No skinned mesh bounds; cannot claim framing")
		envelopes.append(bins)
	print("C198 FRAMING pair=grappler175cm/striker185cm viewport=", camera.get_viewport().get_visible_rect().size)
	var rows: Array = []
	var inside: int = 0
	for tick in 1800:
		room._process(1.0 / 30.0)
		var a: Dictionary = screen_box(room._player_a, envelopes[0])
		var b: Dictionary = screen_box(room._player_b, envelopes[1])
		if a.inside and b.inside:
			inside += 1
		rows.append({"tick": tick + 1, "a": a, "b": b})
	var result: Dictionary = {"frames": 1800, "fps": 30, "seconds": 60, "both_inside": inside,
		"percent": inside / 18.0, "method": "conservative skinned vertex influence envelopes", "rows": rows}
	FileAccess.open("res://.godot/c198/" + str(args.get("out", "framing")) + ".json", FileAccess.WRITE).store_string(JSON.stringify(result))
	print("C198 FRAMING both_inside=", inside, "/1800 percent=", result.percent)
	quit()

reproduction.recorder_gd:
extends SceneTree
## S4e - RECORD THE LIVE ROOM, FROM A CONTAINER WITH NO SCREEN.
##
## THE BLOCKER THIS EXISTS TO CLEAR. Two engine stages landed that the operator
## has never seen move, and the roadmap recorded the reason as "a cloud container
## cannot record it (measured: --write-movie aborts under --headless)". The
## measurement was right and the conclusion was one step too wide: `--headless`
## has no display, and a display is something you can supply.
##
##   xvfb-run -a -s "-screen 0 854x480x24" godot --path Godot \
##     --script tools/record_room.gd --rendering-driver opengl3 \
##     --write-movie out.avi --fixed-fps 30 --resolution 854x480 \
##     --quit-after 450 -- seed=810039 discipline=mma shot=tight
##
## `--quit-after` is FRAMES, so at `--fixed-fps 30` it is thirty per second of
## finished video, and movie mode runs the room on that fixed clock rather than
## on wall time - the recording is the same fight however slowly the container
## renders it. Software GL manages roughly 10% of real time; budget for it.
##
## WHY A TOOL AND NOT THE SCENE. Booting `FightWorldLive.tscn` directly records
## the room's own defaults and nothing else: `configure()` refuses once `setup()`
## has run, and `_ready` runs it. This mounts the scene the way
## `tools/probe_grapple_seam.gd` does - instantiate, configure, THEN set up - so a
## recording can name its seed, its discipline and its A/B.
##
## ARGS, after `--`, all optional:
##   seed=<int>            which bout (the room's own default otherwise)
##   discipline=<name>     boxing | mma | ... (must resolve an arena spec)
##   rounds=<int>
##   shot=<name>           establishing | tight | low_mat (FightCameraRig.SHOTS)
##   speed=<0.1..4.0>      presentation pace; the engine is pumped the same
##   before=1              the OLD room, for the A/B: `engine_positions` and
##                         `body_layers` both off, which is what S4 (2) and
##                         S4 (3) each turned on
##   bare=1                no authored pair exchanges (`pair_moves` off), so the
##                         picture is the engine's own and not a scripted one
##   skin=cc               S61: fighter A wears the Character Creator body
##   hide_arena=<names>    comma-separated `ArenaRig` child names to hide (art
##                         diagnosis only; default recording unchanged)

var rec_room: Node
var camera: Camera3D
var envelopes: Array = []
var frame_rows: Array = []
var frame_inside: int = 0
var output_label: String = "render_framing"

const SCENE := "res://scenes/FightWorldLive.tscn"


func _initialize() -> void:
	var args: Dictionary = _args()
	var scene: PackedScene = load(SCENE) as PackedScene
	if scene == null:
		print("RECORD cannot load %s" % SCENE)
		quit(1)
		return
	var live: Node3D = scene.instantiate() as Node3D
	if args.has("room_script"):
		live.set_script(load(str(args.room_script)))
	if live == null:
		print("RECORD scene did not instantiate")
		quit(1)
		return
	## CONFIGURE BEFORE `add_child`, AND CHECK THAT IT TOOK.
	##
	## S58, 2026-09-23: this tool asked for `discipline=mma seed=810039` and
	## photographed a BOXING RING at seed 94301, three times, while printing the
	## options dict it had intended - a perfect false witness.
	##
	## `add_child` fires `_ready`, `_ready` calls `setup()`, and `setup()` sets
	## `_setup_ran`. `configure()` refuses outright once that is true
	## (`FightWorldLiveScreen.gd:575` - `if _setup_ran: return false`). So every
	## option was silently discarded and nobody checked the return value.
	##
	## `record_room.gd`'s own header has described the correct order since the
	## day it was written - *"instantiate, configure, THEN set up"* - and both
	## tools implemented the opposite. The order below is that header, and the
	## refusal check below it is what makes the header enforceable rather than
	## advisory.

	var options: Dictionary = {"walkout": false, "hit_cam": false, "camera_follow": true, "camera_shot": "establishing", "camera_keep_pair": str(args.get("fit", "false")) == "true", "strikes_play_whole": true, "reactions_play_whole": true, "contact_stop": true, "readable_onset": true, "human_speed_tempo": true}
	if args.has("seed"):
		options["seed"] = int(str(args["seed"]).to_int())
	if args.has("discipline"):
		options["discipline"] = str(args["discipline"])
	if args.has("rounds"):
		options["rounds"] = int(str(args["rounds"]).to_int())
	if args.has("shot"):
		options["camera_shot"] = str(args["shot"])
	## THE A/B, AND IT IS TWO SWITCHES BECAUSE TWO STAGES LANDED. `engine_positions`
	## off restores the band-table walk along the spawn line (S4 (2)); `body_layers`
	## off restores the one-clip body, where a man throwing cannot also step
	## (S4 (3)). Both off IS the room the operator last saw.
	if str(args.get("before", "")) == "1":
		options["engine_positions"] = false
		options["body_layers"] = false
	if str(args.get("bare", "")) == "1":
		options["pair_moves"] = false
	if str(args.get("reactions_play_whole", "")) in ["1", "true", "on"]:
		options["reactions_play_whole"] = true
	if str(args.get("strike_speed_caps", "")) in ["1", "true", "on"]:
		options["strike_speed_caps"] = true
		options["skip_hand_continuity_while_stepping"] = true
	if str(args.get("strikes_play_whole", "")) in ["1", "true", "on"]:
		options["strikes_play_whole"] = true
	if str(args.get("reactions_play_whole", "")) in ["1", "true", "on"]:
		options["reactions_play_whole"] = true
	if str(args.get("human_speed_tempo", "")) in ["1", "true", "on"]:
		options["human_speed_tempo"] = true
	## S68: take four needs C191 contact_stop ON; C188 hit_physics for its A/B.
	for sw in ["contact_stop", "hit_physics"]:
		if str(args.get(sw, "")) in ["1", "true", "on"]:
			options[sw] = true
	if str(args.get("readable_onset", "")) in ["1", "true", "on"]:
		options["readable_onset"] = true
	if args.has("skin"):
		options["fighter_skin"] = str(args["skin"])
	if args.has("hide_arena"):
		var hide_names: Array = []
		for part in str(args["hide_arena"]).split(","):
			var name: String = str(part).strip_edges()
			if not name.is_empty():
				hide_names.append(name)
		if not hide_names.is_empty():
			options["hide_arena"] = hide_names
	if not options.is_empty():
		if not bool(live.call("configure", options)):
			print("%s BAD: configure() REFUSED - the room was already set up, so"
				% "RECORD" + " every option would be silently discarded. Nothing"
				+ " rendered. This is the defect that photographed a boxing ring"
				+ " when asked for mma, three times.")
			quit(1)
			return
	get_root().add_child(live)
	if not bool(live.call("setup")):
		print("RECORD room did not assemble")
		quit(1)
		return
	rec_room = live
	camera = live._find_camera(live)
	output_label = str(args.get("out", "render_framing"))
	if live.has_method("_fit_camera_pair"):
		live._fit_camera_pair(0.0)
	for pair in [[live._node_a, live._player_a], [live._node_b, live._player_b]]:
		var bins: Array = []
		collect(pair[0], pair[1], bins)
		assert(not bins.is_empty())
		envelopes.append(bins)
	RenderingServer.frame_pre_draw.connect(_record_probe)
	print("RECORD options %s" % str(options))
	## NOTHING ELSE TO DO, AND THAT IS THE POINT. The room drives itself from
	## `_process`; movie mode supplies the fixed clock and `--quit-after` ends it.
	## A `_pump_to` here would advance the fight with no frames drawn - the probe's
	## job, not this one's.


func _args() -> Dictionary:
	var out: Dictionary = {}
	for arg in OS.get_cmdline_user_args():
		var a: String = str(arg).strip_edges()
		var eq: int = a.find("=")
		if eq <= 0:
			continue
		out[a.substr(0, eq)] = a.substr(eq + 1)
	return out


func collect(node: Node, player: RefCounted, bins: Array) -> void:
	if node is MeshInstance3D and node.mesh != null and node.is_visible_in_tree():
		var mesh: Mesh = node.mesh
		var skin: Skin = node.skin
		if skin == null:
			skin = player.skeleton().create_skin_from_rest_transforms()
		for surface in mesh.get_surface_count():
			var arrays: Array = mesh.surface_get_arrays(surface)
			var vertices: PackedVector3Array = arrays[Mesh.ARRAY_VERTEX]
			var bones: PackedInt32Array = arrays[Mesh.ARRAY_BONES]
			var weights: PackedFloat32Array = arrays[Mesh.ARRAY_WEIGHTS]
			if bones.is_empty():
				continue
			var stride: int = bones.size() / vertices.size()
			var bounds: Dictionary = {}
			for v in vertices.size():
				for w in stride:
					var at: int = v * stride + w
					if weights[at] <= 0.0:
						continue
					var bind: int = bones[at]
					var point: Vector3 = skin.get_bind_pose(bind) * vertices[v]
					bounds[bind] = (bounds[bind] as AABB).expand(point) if bounds.has(bind) else AABB(point, Vector3.ZERO)
			for bind in bounds:
				var bone: int = skin.get_bind_bone(bind)
				if not skin.get_bind_name(bind).is_empty():
					bone = player.skeleton().find_bone(skin.get_bind_name(bind))
				assert(bone >= 0)
				bins.append({"bone": bone, "box": bounds[bind]})
	for child in node.get_children():
		collect(child, player, bins)

func screen_box(player: RefCounted, bins: Array) -> Dictionary:
	var lo := Vector2(INF, INF)
	var hi := Vector2(-INF, -INF)
	var front: bool = true
	for bin in bins:
		var transform: Transform3D = player.skeleton_world() * player._pose_global(int(bin.bone))
		for corner in 8:
			var point: Vector3 = transform * (bin.box as AABB).get_endpoint(corner)
			front = front and not camera.is_position_behind(point)
			var pixel: Vector2 = camera.unproject_position(point)
			lo = lo.min(pixel)
			hi = hi.max(pixel)
	var size: Vector2 = camera.get_viewport().get_visible_rect().size
	return {"min": [lo.x, lo.y], "max": [hi.x, hi.y], "inside": front and lo.x >= 0.0 and lo.y >= 0.0 and hi.x <= size.x and hi.y <= size.y}


func _record_probe() -> void:
	var a: Dictionary = screen_box(rec_room._player_a, envelopes[0])
	var b: Dictionary = screen_box(rec_room._player_b, envelopes[1])
	if a.inside and b.inside:
		frame_inside += 1
	frame_rows.append({"frame": frame_rows.size() + 1, "a": a, "b": b})
	# Persist every frame, including a final quit-before-next-process frame.
	var result: Dictionary = {"frames": frame_rows.size(), "both_inside": frame_inside,
		"percent": 100.0 * frame_inside / frame_rows.size(), "rows": frame_rows}
	FileAccess.open("res://.godot/c198/" + output_label + ".json", FileAccess.WRITE).store_string(JSON.stringify(result))
	if frame_rows.size() == 1800:
		print("C198 RENDER FRAMING ", frame_inside, "/1800 percent=", result.percent)

reproduction.census_gd:
extends SceneTree
## Posed skin-calibrated capsule census. Every frame, including unowned grapples.
const Caps = preload("res://scripts/FightBodyCapsules.gd")
var args: Dictionary = {}

func _initialize() -> void:
	for arg in OS.get_cmdline_user_args():
		var bits: PackedStringArray = arg.split("=", true, 1)
		if bits.size() == 2:
			args[bits[0]] = bits[1]
	if str(args.get("mode", "")) == "prepare_record":
		prepare_record()
		return
	call_deferred("run")

## Keep record_room.gd as the recorder, without editing its unowned source.
## Generate a scratch derivative adding the options it does not yet expose and
## a deterministic pre-roll. Parse it, then launch via Tools/godot_hidden.ps1.
func prepare_record() -> void:
	var source: String = FileAccess.get_file_as_string("res://tools/record_room.gd")
	var settings: String = '{"strikes_play_whole": true, "reactions_play_whole": true, "contact_stop": %s, "walkout": false, "hit_cam": false, "camera_follow": true, "camera_keep_pair": true, "camera_shot": "establishing"}' % str(args.get("stop", "false"))
	source = source.replace("var options: Dictionary = {}", "var options: Dictionary = " + settings)
	var preroll: String = "\tlive.set_process(false)\n\tfor frame in 2832:\n\t\tlive._process(1.0 / 60.0)\n\tlive.set_process(true)\n\tvar camera: Camera3D = live._find_camera(live)\n\tcamera.position = Vector3(3.4, 5.0, 6.0)\n\tcamera.transform = Transform3D(Basis.looking_at(Vector3(0.0, 2.1, 0.0) - camera.position, Vector3.UP), camera.position)\n\tcamera.fov = 48.0\n"
	source = source.replace('\tprint("RECORD options %s" % str(options))', preroll + '\tprint("RECORD options %s" % str(options))')
	DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path("res://.godot/c191"))
	var path: String = "res://.godot/c191/record_" + str(args.get("stop", "false")) + ".gd"
	FileAccess.open(path, FileAccess.WRITE).store_string(source)
	print("C191 RECORD derivative of tools/record_room.gd: ", path)
	quit()

func run() -> void:
	var room: Node = load("res://scenes/FightWorldLive.tscn").instantiate()
	if args.has("room_script"):
		room.set_script(load(str(args.room_script)))
	var whole: bool = str(args.get("whole", "true")) == "true"
	assert(room.configure({"seed": 92012, "discipline": "mma", "strikes_play_whole": whole,
		"reactions_play_whole": whole, "contact_stop": str(args.get("stop", "false")) == "true",
		"readable_onset": true, "human_speed_tempo": true, "walkout": false, "hit_cam": false, "camera_follow": true, "camera_keep_pair": true, "camera_shot": "establishing"}))
	root.add_child(room)
	assert(room.setup())
	room.set_process(false)
	print("C191 PAIR grappler=", room._height_a_m, "m striker=", room._height_b_m, "m whole=", whole)
	print("C191 RADII ", room._body_a.capsules_out)
	var rows: Array = []
	var contacts: Array = []
	var poses: Array = []
	var gaps: Array = []
	var owners: Dictionary = {}
	var pairs: Dictionary = {}
	var count: int = 0
	var run_length: int = 0
	var longest: int = 0
	var clinch_proved: bool = false
	for tick in 3600:
		room._process(1.0 / 60.0)
		var hit: Dictionary = Caps.frame_overlap(room._player_a.skeleton(), room._player_b.skeleton(), room._body_a, room._body_b)
		var owner: String = "unowned_locomotion_guard"
		if not room._grapple.is_empty():
			owner = "unowned_grapple"
		elif room._player_a.whole_active() or room._player_b.whole_active():
			owner = "whole_strike"
		elif not room._pair.is_empty():
			owner = "authored_pair"
		elif not room._player_a.strike_contact().is_empty() or not room._player_b.strike_contact().is_empty():
			owner = "legacy_strike"
		elif str(room._player_a.animation_player().current_animation).begins_with("react") or str(room._player_b.animation_player().current_animation).begins_with("react"):
			owner = "unowned_reaction"
		var a: AnimationPlayer = room._player_a.animation_player()
		var b: AnimationPlayer = room._player_b.animation_player()
		var row: Dictionary = {"tick": tick + 1, "seconds": (tick + 1) / 60.0, "depth": hit.depth,
			"owner": owner, "a": a.current_animation, "b": b.current_animation, "pairs": hit.pairs,
			"a_clock": a.current_animation_position, "b_clock": b.current_animation_position}
		rows.append(row)
		gaps.append(room._player_a.bone_world("Hips").distance_to(room._player_b.bone_world("Hips")))
		var pose: Array = []
		for player in [room._player_a, room._player_b]:
			pose.append(player.skeleton_world())
			for bone in player.skeleton().get_bone_count():
				pose.append(player.skeleton().get_bone_pose(bone))
		poses.append(var_to_bytes(pose).hex_encode().sha256_text())
		for side in ["a", "b"]:
			var player: RefCounted = room._player_a if side == "a" else room._player_b
			var foe: RefCounted = room._player_b if side == "a" else room._player_a
			var hold: Dictionary = room._whole_roots.get(side, {})
			var info: Dictionary = player.strike_contact()
			if player.whole_active() and bool(hold.get("landed", false)) and not info.is_empty():
				var clock: float = float(info.position_s)
				if clock >= float(info.contact_s) and clock < float(info.contact_s) + 1.0 / 60.0:
					var self_body: Dictionary = room._body_a if side == "a" else room._body_b
					var foe_body: Dictionary = room._body_b if side == "a" else room._body_a
					var self_parts: Array = Caps.posed_parts(player.skeleton(), self_body)
					var foe_parts: Array = Caps.posed_parts(foe.skeleton(), foe_body)
					var effector: String = str(info.hand)
					if player._is_kick_throw_role(str(info.take)) or str(info.take).contains("knee"):
						var names: Array = ["LeftFoot", "RightFoot"]
						if str(info.take).contains("knee"):
							names = ["LeftLowerLeg", "RightLowerLeg"]
						var anim: Animation = player.animation_player().get_animation(str(info.take))
						var tracks: Dictionary = player._bone_tracks(anim)
						var travel: float = -1.0
						for name in names:
							var bone: int = player.skeleton().find_bone(name)
							var start: Vector3 = player._sample_global(bone, anim, tracks, 0.0).origin
							var end: Vector3 = player._sample_global(bone, anim, tracks, float(info.contact_s)).origin
							if start.distance_to(end) > travel:
								travel = start.distance_to(end)
								effector = name + "-" + name.replace("Foot", "Toes").replace("LowerLeg", "Foot")
					var closest: float = -100.0
					var target_class: String = "head" if str(hold.region) == "head_neck" else ("leg" if str(hold.region).ends_with("leg") else "torso")
					for pa in self_parts:
						if str(pa.name) != effector:
							continue
						for pb in foe_parts:
							if str(pb["class"]) == target_class:
								closest = maxf(closest, Caps.pair_depth(pa, pb))
					contacts.append({"tick": tick + 1, "side": side, "take": info.take, "region": hold.region, "surface_depth": closest, "effector": effector})
		if float(hit.depth) > 0.03:
			count += 1
			run_length += 1
			longest = maxi(longest, run_length)
			owners[owner] = int(owners.get(owner, 0)) + 1
			var seen: Dictionary = {}
			for pair in hit.pairs:
				if float(pair.depth) > 0.03:
					var key: String = str(pair.a_name) + " / " + str(pair.b_name)
					seen[key] = true
			for key in seen:
				pairs[key] = int(pairs.get(key, 0)) + 1
		else:
			run_length = 0
		if not clinch_proved and (str(a.current_animation).contains("clinch") or str(b.current_animation).contains("clinch")) and float(hit.depth) > 0.03:
			clinch_proved = true
			print("C191 POSITIVE CLINCH ", JSON.stringify(row))
	var worst: Array = rows.duplicate()
	worst.sort_custom(func(a: Dictionary, b: Dictionary) -> bool: return float(a.depth) > float(b.depth))
	var result: Dictionary = {"whole": whole, "frames": rows, "overlap_frames": count,
		"share": count / 3600.0, "longest_s": longest / 60.0, "owner_frames": owners,
		"pair_frames": pairs, "worst": worst.slice(0, 10), "clinch_proved": clinch_proved, "contacts": contacts, "pose_hashes": poses, "hip_gaps": gaps,
		"event_hash": var_to_bytes(room._state["fight"]["log"]).hex_encode().sha256_text(),
		"calibration_a": room._body_a.capsules_out, "calibration_b": room._body_b.capsules_out,
		"scale_a": room._body_a.scale, "scale_b": room._body_b.scale}
	DirAccess.make_dir_recursive_absolute(ProjectSettings.globalize_path("res://.godot/c191"))
	var file: FileAccess = FileAccess.open("res://.godot/c191/" + str(args.get("out", "on")) + ".json", FileAccess.WRITE)
	file.store_string(JSON.stringify(result))
	print("C191 CENSUS count=", count, " share=", result.share, " longest_s=", result.longest_s, " owners=", owners, " clinch_proved=", clinch_proved)
	quit(0 if clinch_proved else 1)
